INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs) VALUES
  (189, 1, '숫자로 정렬하기', '`10`, `9`, `100`, `2` 가 한 줄씩 든 파일을 `sort` 와 `sort -n` 으로 정렬하면 각각 어떤 순서가 될까요?', '기본 정렬은 글자 순서예요.', NULL, NULL, '[]', 'choice', '["`sort` 도 숫자 크기로 `2 9 10 100` 이 된다", "`sort -n` 은 `10 100 2 9` 가 된다", "`sort` 는 글자 순서라 `10 100 2 9`, `sort -n` 은 숫자 크기라 `2 9 10 100` 이 된다. `sort -nr` 은 큰 수부터 `100 10 9 2` 이다", "`sort -n` 은 `9 2 10 100` 처럼 입력 순서를 유지한다"]', 2, '숫자 열을 정렬할 때 `-n` 을 빠뜨리면 `100` 이 `2` 보다 앞에 옵니다.', NULL, NULL, NULL, NULL),
  (189, 2, '-k 로 필드 정렬', '쉼표로 나뉜 `이름,나이,도시` 줄들을 나이순(숫자)으로 정렬하려면 어떻게 쓸까요? 나이가 같으면 이름 순서는 어떻게 될까요?', '구분자는 `-t`, 기준 열은 `-k` 예요.', NULL, NULL, '[]', 'choice', '["`sort -d, -k2n` 으로 쓴다", "`sort -t, -k2n` 으로 쓴다. 나이가 같은 줄은 마지막에 줄 전체를 비교하므로 이름이 사전순으로 놓인다 (예: `bob` 다음 `carol`)", "`sort -k2n` 만으로 쉼표를 자동으로 구분한다", "나이가 같으면 입력 순서가 항상 유지된다"]', 1, '`-k2n` 처럼 `n` 을 붙이지 않으면 `-k2` 는 2번째 필드부터 줄 끝까지를 글자로 비교합니다.', NULL, NULL, NULL, NULL),
  (189, 3, '-k2 와 -k2,2 의 차이', '`sort -t, -k2` 는 2번째 필드부터 어디까지를 정렬 기준으로 삼을까요? 2번째 필드만 쓰려면요?', '끝 위치를 지정하지 않으면 줄 끝까지예요.', NULL, NULL, '[]', 'choice', '["시작 필드를 줄 끝까지 기준으로 삼는다. 2번째 필드만 기준으로 쓰려면 `-k2,2` 처럼 끝 필드도 쓴다", "2번째 필드만 기준으로 쓴다", "1번째 필드부터 2번째까지 쓴다", "`-k2` 는 문법 오류이다"]', 0, '`-k2,2n -k1,1r` 처럼 키를 여러 개 이어서 쓰면 앞의 키가 같을 때 다음 키를 씁니다.', NULL, NULL, NULL, NULL),
  (189, 4, '-k 와 -u 로 중복 제거', '`sort -t, -k3,3 -u` 를 쓰면 도시(3번째 필드)가 같은 줄은 어떻게 될까요?', '-u 는 기준이 같은 줄을 하나로 줄여요.', NULL, NULL, '[]', 'choice', '["줄 전체가 같을 때만 중복으로 본다", "도시가 같은 줄이 모두 사라진다", "도시가 같은 줄이 모두 남고 정렬만 된다", "기준 필드(`-k3,3`) 값이 같은 줄은 한 줄만 남는다 (예: 도시가 `seoul` 인 `bob` 과 `dave` 중 입력에서 앞선 `bob` 만 남음)"]', 3, '`-u` 만 쓰면 줄 전체가 같은 줄을 하나로 줄입니다.', NULL, NULL, NULL, NULL),
  (189, 5, '사람이 읽는 크기 정렬', '`1K`, `1M`, `1G`, `500` 이 든 파일을 크기 순으로 정렬하려면 어떤 옵션을 쓸까요?', '`du -h` 출력 정렬에 쓰는 옵션이에요.', NULL, NULL, '[]', 'choice', '["`sort -n` 이 `K`, `M`, `G` 를 반영한다", "`sort -r` 이 크기 순으로 정렬한다", "`sort -h` 를 쓰면 `500 1K 1M 1G` 순으로 K, M, G 접미사를 반영해 정렬한다. `-n` 은 접미사를 크기로 읽지 못한다", "`sort -s` 가 크기 순으로 정렬한다"]', 2, '`sort -n` 은 `1K` 의 `K` 를 크기로 반영하지 못해 `1K 500` 순서가 됩니다.', NULL, NULL, NULL, NULL),
  (189, 6, 'uniq 는 이웃한 줄만', '`b a b a c` 가 한 줄씩 든 파일에 `uniq` 만 쓰면 어떻게 될까요? 횟수를 세려면요?', '연속으로 같은 줄만 합쳐요.', NULL, NULL, '[]', 'choice', '["`uniq` 만으로도 `a b c` 가 된다", "이웃한 같은 줄만 합치므로 정렬되지 않은 입력은 그대로 `b a b a c` 가 나온다. `sort | uniq -c` 로 정렬한 뒤 세면 `2 a`, `2 b`, `1 c` 가 나온다", "`uniq -c` 는 정렬하지 않아도 전체 횟수를 센다", "`uniq` 는 파일 전체에서 중복을 모두 찾는다"]', 1, '`sort | uniq -d` 는 중복된 줄만, `sort | uniq -u` 는 한 번만 나온 줄만 보여 줍니다.', NULL, NULL, NULL, NULL),
  (189, 7, '정렬 여부 확인', '`sort -c 파일` 은 무엇을 할까요? 정렬되어 있지 않을 때와 되어 있을 때 종료 코드는요?', '파일을 바꾸지 않고 검사만 해요.', NULL, NULL, '[]', 'choice', '["정렬은 하지 않고 이미 정렬되어 있는지만 검사한다. 어긋나면 `disorder` 메시지와 종료 코드 1, 정렬되어 있으면 아무 출력 없이 종료 코드 0 이다", "파일을 정렬해 덮어쓴다", "줄 수를 센다", "정렬되어 있지 않아도 종료 코드는 0 이다"]', 0, '정렬 결과를 같은 파일에 쓰려면 `sort -o 파일 파일` 을 씁니다. `sort 파일 > 파일` 은 먼저 파일이 비워져 내용이 사라집니다.', NULL, NULL, NULL, NULL),
  (189, 8, 'cut 의 필드 지정', '`cut -d, -f2-` 와 `cut -d, -f-2` 와 `cut -d, -f1,3` 은 쉼표로 나뉜 `bob,30,seoul` 에서 각각 무엇을 출력할까요?', '하이픈의 위치가 시작인지 끝인지 봐요.', NULL, NULL, '[]', 'choice', '["`-f2-` 는 `30` 만 출력한다", "`-f-2` 는 `30` 만 출력한다", "`-f1,3` 은 `bob,30,seoul` 전체를 출력한다", "`-f2-` 는 2번째부터 끝까지라 `30,seoul`, `-f-2` 는 처음부터 2번째까지라 `bob,30`, `-f1,3` 은 1번째와 3번째라 `bob,seoul` 이다"]', 3, '`--complement` 를 쓰면 지정한 필드를 뺀 나머지를 출력합니다 (`-f2` 이면 `bob,seoul`).', NULL, NULL, NULL, NULL),
  (189, 9, '구분자가 없는 줄', '`abc` 와 `a,b` 두 줄에 `cut -d, -f2` 를 하면 어떻게 될까요? `-s` 를 붙이면요?', '구분자가 없는 줄의 처리가 달라져요.', NULL, NULL, '[]', 'choice', '["`abc` 는 빈 줄로 출력된다", "`abc` 는 오류가 나서 명령이 멈춘다", "구분자가 없는 줄 `abc` 는 그대로 출력되고 `a,b` 는 `b` 가 나온다. `-s` 를 붙이면 구분자가 없는 줄은 건너뛰어 `b` 만 나온다", "`-s` 를 붙이면 `abc` 도 `a` 가 출력된다"]', 2, '탭이 기본 구분자라 `-d` 를 생략하면 탭으로 나뉜 필드를 자릅니다.', NULL, NULL, NULL, NULL),
  (189, 10, 'cut 의 글자 단위 자르기', '`cut -c1-3` 은 `bob,30,seoul` 에서 무엇을 출력할까요? `-b1` 은 `alice,25,busan` 에서요?', '필드가 아니라 위치로 잘라요.', NULL, NULL, '[]', 'choice', '["`-c1-3` 은 `bob,30` 을 출력한다", "`-c1-3` 은 처음 3글자 `bob`, `-b1` 은 첫 바이트 `a` 를 출력한다. 필드 구분자와 상관없이 위치로 자른다", "`-b1` 은 첫 단어 `alice` 를 출력한다", "`-c` 는 구분자 `-d` 가 반드시 필요하다"]', 1, '`-b` 는 바이트 단위로 자르며, 영문에서는 `-c` 와 결과가 같습니다.', NULL, NULL, NULL, NULL),
  (189, 11, 'paste 로 줄 합치기', '`1 2 3` 이 든 `a.txt` 와 `x y z` 가 든 `b.txt` 에 `paste a.txt b.txt` 와 `paste -d, a.txt b.txt` 는 각각 어떻게 나올까요? `paste -sd, a.txt` 는요?', '파일을 나란히 붙이고 기본 구분자는 탭이에요.', NULL, NULL, '[]', 'choice', '["`paste a.txt b.txt` 는 줄마다 탭으로 이어 `1`(탭)`x` 형태이고, `-d,` 를 주면 `1,x` 이다. `paste -sd, a.txt` 는 한 파일의 모든 줄을 쉼표로 이어 `1,2,3` 한 줄이 된다", "`paste a.txt b.txt` 는 `a.txt` 를 모두 출력한 뒤 `b.txt` 를 출력한다", "`-d,` 는 줄 끝에만 쉼표를 붙인다", "`-s` 는 파일을 정렬한다"]', 0, '`paste - - < 파일` 은 입력을 두 줄씩 한 줄로 묶습니다 (줄 수가 홀수면 마지막 줄 뒤가 빕니다).', NULL, NULL, NULL, NULL),
  (189, 12, 'join 의 조건', '`join j1.txt j2.txt` 는 두 파일을 어떻게 합칠까요? 한쪽에만 있는 줄은 어떻게 볼 수 있을까요?', '첫 번째 필드가 같은 줄끼리 합쳐요.', NULL, NULL, '[]', 'choice', '["두 파일의 줄 번호가 같은 줄끼리 합친다", "한쪽에만 있는 줄도 기본으로 출력한다", "`-v1` 은 양쪽에 모두 있는 줄만 출력한다", "첫 번째 필드 값이 같은 줄끼리 이어 붙이고, 양쪽에 모두 있는 키만 출력한다. 첫 파일에만 있는 줄은 `-a1` 로 함께 출력하거나 `-v1` 로 그 줄만 볼 수 있다"]', 3, '입력이 키로 정렬되어 있지 않으면 `input is not in sorted order` 오류가 납니다.', NULL, NULL, NULL, NULL),
  (189, 13, 'comm 의 세 열', '정렬된 `m1`(`a b c`)과 `m2`(`b c d`)에 `comm -12`, `comm -23`, `comm -13` 을 쓰면 각각 무엇이 나올까요?', '숫자는 숨길 열을 뜻해요.', NULL, NULL, '[]', 'choice', '["`comm -12` 는 `a d` 를 출력한다", "`comm -23` 은 `d` 를 출력한다", "`comm -12` 는 둘 다에 있는 `b c`, `comm -23` 은 `m1` 에만 있는 `a`, `comm -13` 은 `m2` 에만 있는 `d` 이다. 옵션의 숫자는 출력하지 않을 열(1 은 첫 파일만, 2 는 둘째만, 3 은 공통)이다", "`comm -13` 은 `b c` 를 출력한다"]', 2, '입력이 정렬되어 있지 않으면 `not in sorted order` 메시지가 나옵니다.', NULL, NULL, NULL, NULL),
  (189, 14, 'nl 의 빈 줄 처리', '첫째 줄 `a`, 둘째 줄 빈 줄, 셋째 줄 `b` 인 파일에 `nl` 을 쓰면 번호는 어떻게 붙을까요? 빈 줄에도 붙이려면요?', '기본값은 비어 있지 않은 줄만이에요.', NULL, NULL, '[]', 'choice', '["빈 줄을 포함해 모든 줄에 항상 번호가 붙는다", "기본은 비어 있지 않은 줄에만 번호가 붙어 `1 a`, (번호 없는 빈 줄), `2 b` 가 된다. `nl -ba` 를 쓰면 빈 줄에도 번호가 붙어 `1 a`, `2`, `3 b` 가 된다", "번호가 붙지 않고 줄 내용만 출력된다", "빈 줄이 삭제되어 `1 a`, `2 b` 가 출력된다"]', 1, '`nl` 의 번호는 기본으로 6칸 폭에 맞춰 오른쪽 정렬되고 탭으로 구분됩니다.', NULL, NULL, NULL, NULL),
  (189, 15, '숫자 정렬', '숫자 크기 순서로 정렬하는 `sort` 옵션을 채우세요.', '"numeric" 의 첫 글자예요.', NULL, NULL, '[]', 'fill', '["-n", "-h", "-u", "-d"]', NULL, '`-n` 이 없으면 글자 순서라 `100` 이 `9` 보다 앞에 옵니다.', '[0]', 'sort {0} n.txt', NULL, NULL),
  (189, 16, '거꾸로 정렬', '정렬 순서를 거꾸로 하는 `sort` 옵션을 채우세요.', '"reverse" 의 첫 글자예요.', NULL, NULL, '[]', 'fill', '["-r", "-u", "-c", "-o"]', NULL, '`-nr` 은 숫자 큰 순서입니다.', '[0]', 'sort {0} n.txt', NULL, NULL),
  (189, 17, '구분자 지정', '`sort` 에서 쉼표를 필드 구분자로 정하는 옵션을 채우세요.', '"separator" 라는 뜻의 한 글자 옵션이에요.', NULL, NULL, '[]', 'fill', '["-t", "-d", "-s", "-f"]', NULL, '`cut` 에서는 같은 일을 `-d` 로 합니다.', '[0]', 'sort {0}, -k2n p.csv', NULL, NULL),
  (189, 18, '중복 줄 제거', '정렬하면서 같은 줄을 하나로 줄이는 `sort` 옵션을 채우세요.', '"unique" 의 첫 글자예요.', NULL, NULL, '[]', 'fill', '["-u", "-n", "-r", "-c"]', NULL, '`sort -u` 는 `sort | uniq` 와 같은 결과를 냅니다.', '[0]', 'sort {0} d.txt', NULL, NULL),
  (189, 19, '횟수 세기', '`uniq` 에서 각 줄이 몇 번 나왔는지 앞에 붙이는 옵션을 채우세요.', '"count" 의 첫 글자예요.', NULL, NULL, '[]', 'fill', '["-c", "-d", "-u", "-n"]', NULL, '`uniq` 는 이웃한 줄만 합치므로 먼저 `sort` 로 정렬합니다.', '[0]', 'sort d.txt | uniq {0}', NULL, NULL),
  (189, 20, '필드 자르기', '`cut` 으로 쉼표 구분 줄의 2번째 필드를 출력하는 옵션을 채우세요.', '"field" 의 첫 글자예요.', NULL, NULL, '[]', 'fill', '["-f", "-c", "-k", "-t"]', NULL, '`-f-2` 는 처음부터 2번째, `-f2-` 는 2번째부터 끝까지입니다.', '[0]', 'cut -d, {0}2 p.csv', NULL, NULL),
  (189, 21, '글자 위치로 자르기', '각 줄의 처음 3글자를 출력하는 `cut` 옵션을 채우세요.', '"character" 의 첫 글자예요.', NULL, NULL, '[]', 'fill', '["-c", "-f", "-d", "-s"]', NULL, '`-b` 는 바이트 단위로 자릅니다.', '[0]', 'cut {0}1-3 p.csv', NULL, NULL),
  (189, 22, '한 줄로 이어 붙이기', '`paste` 로 한 파일의 모든 줄을 쉼표로 이어 한 줄로 만드는 옵션을 채우세요.', '두 옵션을 이어 쓰며 첫 글자는 "serial" 이에요.', NULL, NULL, '[]', 'fill', '["-s", "-r", "-c", "-j"]', NULL, '결과는 `1,2,3` 처럼 한 줄입니다.', '[0]', 'paste {0}d, a.txt', NULL, NULL),
  (189, 23, '공통 줄만 보기', '`comm` 으로 두 정렬된 파일에 모두 있는 줄만 보이도록 숨길 열 번호를 채우세요.', '첫째와 둘째 파일에만 있는 열을 숨겨요.', NULL, NULL, '[]', 'fill', '["12", "13", "23", "3"]', NULL, '`-23` 은 첫째 파일에만 있는 줄을 보여 줍니다.', '[0]', 'comm -{0} m1 m2', NULL, NULL),
  (189, 24, '파일 이름만 뽑기', '경로 `/a/b/c.txt` 에서 마지막 이름 `c.txt` 만 출력하는 명령을 채우세요.', '"기본 이름"이라는 뜻의 영어 단어예요.', NULL, NULL, '[]', 'fill', '["basename", "dirname", "filename", "pathname"]', NULL, '`dirname /a/b/c.txt` 는 `/a/b` 를 출력합니다.', '[0]', '{0} /a/b/c.txt', NULL, NULL),
  (189, 25, '줄 번호 붙이기', '모든 줄(빈 줄 포함)에 번호를 붙이도록 `nl` 에 붙이는 옵션을 채우세요.', 'body 를 all 로 한다는 뜻이에요.', NULL, NULL, '[]', 'fill', '["-ba", "-n", "-s", "-w"]', NULL, '기본값은 빈 줄에 번호를 붙이지 않습니다.', '[0]', 'nl {0} e.txt', NULL, NULL),
  (189, 26, '정렬되지 않은 목록에서 빈도 순위 만들기', '로그에서 뽑은 단어 목록의 빈도 순위를 만드는 순서입니다. 순서에 맞게 놓아 보세요.', '정렬 → 횟수 세기 → 많은 순 정렬 순서예요.', NULL, NULL, '[]', 'order', '["`sort 파일` 로 같은 줄이 이웃하게 정렬한다", "`uniq -c` 로 각 줄의 횟수를 앞에 붙인다", "`sort -nr` 로 횟수가 큰 순서로 다시 정렬한다", "`head -n 3` 으로 상위 3개만 본다"]', NULL, '첫 정렬을 빠뜨리면 이웃하지 않은 같은 줄을 합치지 못합니다.', '[0, 1, 2, 3]', NULL, NULL, NULL),
  (189, 27, 'CSV 에서 열 뽑아 나이순 보기', '쉼표로 나뉜 파일에서 이름과 나이만 뽑아 나이순으로 보는 순서입니다. 순서에 맞게 놓아 보세요.', '자르기 → 정렬 → 확인 순서예요.', NULL, NULL, '[]', 'order', '["`cut -d, -f1,2 p.csv` 로 이름과 나이 열만 뽑는다", "`sort -t, -k2n` 으로 나이 숫자 순서로 정렬한다", "`head -n 1` 로 가장 어린 사람을 본다", "`tail -n 1` 로 가장 나이 많은 사람을 본다"]', NULL, '`-k2n` 의 `n` 을 빠뜨리면 `5` 가 `25` 보다 뒤로 갑니다.', '[0, 1, 2, 3]', NULL, NULL, NULL),
  (189, 28, '두 목록의 차이 구하기', '정렬되지 않은 두 목록에서 첫 목록에만 있는 항목을 구하는 순서입니다. 순서에 맞게 놓아 보세요.', '정렬 → 정렬 → 비교 → 확인 순서예요.', NULL, NULL, '[]', 'order', '["`sort a.txt > a.sorted` 로 첫 목록을 정렬한다", "`sort b.txt > b.sorted` 로 둘째 목록을 정렬한다", "`comm -23 a.sorted b.sorted` 로 첫 목록에만 있는 항목을 본다", "결과가 비었는지 `wc -l` 로 줄 수를 센다"]', NULL, '`comm` 은 정렬된 입력이 필요합니다.', '[0, 1, 2, 3]', NULL, NULL, NULL),
  (189, 29, '두 파일을 키로 합치기', '사람 번호와 이름이 든 파일, 번호와 도시가 든 파일을 번호로 합치는 순서입니다. 순서에 맞게 놓아 보세요.', '정렬 → 합치기 → 확인 순서예요.', NULL, NULL, '[]', 'order', '["두 파일이 첫 번째 필드(번호)로 정렬되어 있는지 `sort -c` 로 검사한다", "정렬되어 있지 않으면 `sort` 로 정렬한 파일을 만든다", "`join j1.txt j2.txt` 로 번호가 같은 줄을 합친다", "한쪽에만 있는 줄은 `join -v1` 로 따로 확인한다"]', NULL, '`join -o 1.2,2.2` 처럼 출력할 필드를 고를 수 있습니다.', '[0, 1, 2, 3]', NULL, NULL, NULL);
